private function distance(int $a, int $b): int
{
    [$x, $y] = $this->point($a);
    [$u, $v] = $this->point($b);
    return abs($x - $u) + abs($y - $v);
private function length(array $route): int
{
    $result = 0;
    $previous = 0;
    foreach ($route as $id) {
        $result += $this->distance($previous, $id);
        $previous = $id;
    }
    return $result + $this->distance($previous, 0);
